using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Metric;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" score;
data Node { value::i64; next::ref<Node>; }
symbol @arena::region, @gain::i64;
effect @arena <- region(4096u64);
effect @gain <- 10;
function make_node(arena::region, x::Metric, gain::i64)::ref<Node> {
 alloc arena Node(score(x) + gain, null)
}
proc build(x::Metric)->ref<Node> { make_node(@arena, x, @gain) }
export Node; export build; export @arena; export @gain;

