using symbol "std:io" @print;
using symbol "std:io" @assert;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Sample;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Metric;
using "adapter.cod" Output;
using "adapter.cod" adapted;
using "adapter.cod" frozen;
symbol from "factory.cod" @arena;
symbol from "factory.cod" @gain;
symbol @selected::proc(Metric)->ref<Output>, @original::proc(Metric)->ref<Output>;
effect @selected <- adapted;
effect @original <- frozen;
effect @arena <- region(8192u64);
effect @gain <- 20;
data Node { unrelated::bool; }
{
 let sample = create(@arena);
 let baseline = used_bytes(@arena);
 behave @print(deref(perform @original(sample)).value);
 let retained = {
  effect @arena <- region(4096u64);
  behave @print(deref(frozen(sample)).value);
  behave @print(deref(adapted(sample)).value);
  let first = adapted(sample);
  let second = behave @selected(sample);
  setfield(first, next, second);
  behave @print(deref(deref(first).next).value);
  perform @selected(sample)
 };
 behave @print(deref(retained).value);
 setfield(retained, value, 19);
 let next = perform @selected(sample);
 setfield(retained, next, next);
 behave @print(deref(retained).value);
 behave @print(deref(deref(retained).next).value);
 behave @assert(used_bytes(@arena) == baseline);
 behave @print(@gain);
};

