using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Metric;
using "adapter.cod" Output;
symbol @task::proc(Metric)->ref<Output>;
proc captured(p::proc(Metric)->ref<Output>, x::Metric)->ref<Output> {
 effect @task <- p;
 perform @task(x)
}
proc current(p::proc(Metric)->ref<Output>, x::Metric)->ref<Output> {
 effect @task <- p;
 behave @task(x)
}
export captured; export current;

